import{_ as s,C as i,o as t,c as l,a2 as a,b as n,w as o,a as h,E as d,a3 as c}from"./chunks/framework.Bqn-bhhR.js";const y=JSON.parse('{"title":"Health Status & Resolution","description":"","frontmatter":{},"headers":[],"relativePath":"guide/health-status.md","filePath":"guide/health-status.md","lastUpdated":1786047222000}'),u={name:"guide/health-status.md"};function m(p,e,k,f,g,b){const r=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="health-status-resolution" tabindex="-1">Health Status &amp; Resolution <a class="header-anchor" href="#health-status-resolution" aria-label="Permalink to &quot;Health Status &amp; Resolution&quot;">​</a></h1><p>Code moves. Every time you resolve or heal a bookmark, Codemark re-runs the stored structural query against the <em>current</em> tree and computes a health status. This page covers the tiered resolution pipeline in <code>crates/codemark-core/src/engine/</code>.</p><h2 id="the-status-enums" tabindex="-1">The status enums <a class="header-anchor" href="#the-status-enums" aria-label="Permalink to &quot;The status enums&quot;">​</a></h2><p>There are two relevant enums:</p><ul><li><strong><code>ResolutionMethod</code></strong> — <em>how</em> a match was found: <code>Exact | Relaxed | HashFallback | Failed</code></li><li><strong><code>BookmarkHealth</code></strong> — the resulting state: <code>Active | Drifted | Stale | Archived</code></li></ul><p>(An additional UI-only <code>LiveUIStatus</code> — <code>Healthy | Drifted | Broken</code> — is used for transient TUI previews.)</p><h2 id="the-resolution-pipeline" tabindex="-1">The resolution pipeline <a class="header-anchor" href="#the-resolution-pipeline" aria-label="Permalink to &quot;The resolution pipeline&quot;">​</a></h2>',7)),(t(),n(c,null,{default:o(()=>[d(r,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22bookmark%5Cn(stored%20query%20%2B%20content_hash)%22%5D%20--%3E%20P%5Bparse%20current%20file%5D%0A%20%20P%20--%3E%20T1%7B%22Tier%201%20%E2%80%94%20Exact%5Cnrun%20query%20verbatim%22%7D%0A%20%20T1%20--%20%221%20match%22%20--%3E%20OK%5B%22Exact%20%E2%86%92%20Active%22%5D%0A%20%20T1%20--%20%220%20or%20many%22%20--%3E%20T2%7B%22Tier%202%20%E2%80%94%20Relaxed%5Cnstrip%20%23eq%3F%20predicates%22%7D%0A%20%20T2%20--%20%221%20match%22%20--%3E%20REL%5B%22Relaxed%20%E2%86%92%20Drifted%22%5D%0A%20%20T2%20--%20%220%20or%20many%22%20--%3E%20T3%7B%22Tier%203%20%E2%80%94%20Minimal%5Cninnermost%20%40target%20only%22%7D%0A%20%20T3%20--%20%221%20match%22%20--%3E%20MIN%5B%22Relaxed%20%E2%86%92%20Drifted%22%5D%0A%20%20T3%20--%20%220%20or%20many%22%20--%3E%20T4%7B%22Tier%204%20%E2%80%94%20HashFallback%5Cnwalk%20all%20nodes%2C%5Cnmatch%20content_hash%22%7D%0A%20%20T4%20--%20found%20--%3E%20HASH%5B%22HashFallback%20%E2%86%92%20Drifted%22%5D%0A%20%20T4%20--%20not%20found%20--%3E%20FAIL%5B%22Failed%20%E2%86%92%20Stale%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>Resolution operates on a <strong>single file</strong>. There is no directory walk — cross-repo concerns are handled at the database/registry layer, not the resolver.</p><h3 id="how-each-tier-works" tabindex="-1">How each tier works <a class="header-anchor" href="#how-each-tier-works" aria-label="Permalink to &quot;How each tier works&quot;">​</a></h3><ul><li><strong>Tier 1 — Exact.</strong> Run the stored <code>bookmark.query</code> verbatim. If it yields exactly one match, the method is <code>Exact</code>.</li><li><strong>Tier 2 — Relaxed.</strong> <code>relax_query</code> strips every <code>(#eq? …)</code>/<code>(#match? …)</code> text predicate via regex, keeping the structural nesting. This widens the match set (e.g. matches all methods in a class instead of one).</li><li><strong>Tier 3 — Minimal.</strong> <code>minimize_query</code> discards all ancestor structure and keeps only the innermost node pattern carrying <code>@target</code> plus its <code>@fn_name</code> predicate. Both Tier 2 and Tier 3 report as <code>Relaxed</code>.</li><li><strong>Tier 4 — HashFallback.</strong> Only when <code>bookmark.content_hash</code> is present. A recursive pre-order walk hashes every named node&#39;s source text and returns the first whose hash equals the stored one. This is how a bookmark survives a file rename or method extraction.</li></ul><h3 id="a-tier-only-fires-if-the-previous-one-failed" tabindex="-1">A tier only fires if the previous one failed <a class="header-anchor" href="#a-tier-only-fires-if-the-previous-one-failed" aria-label="Permalink to &quot;A tier only fires if the previous one failed&quot;">​</a></h3><p>Within a tier, if there are <em>multiple</em> matches and none of them hash-match the stored content hash, the result is <code>None</code> — it falls through to the next tier rather than guessing. This is the key correctness property: the resolver never silently picks the wrong node.</p><h2 id="how-health-is-computed" tabindex="-1">How health is computed <a class="header-anchor" href="#how-health-is-computed" aria-label="Permalink to &quot;How health is computed&quot;">​</a></h2><p><code>health::transition()</code> is a <strong>pure function of (method, hash_matches)</strong> — time parameters exist in the signature but are currently ignored:</p><table tabindex="0"><thead><tr><th>Method</th><th>hash_matches?</th><th>Resulting health</th></tr></thead><tbody><tr><td><code>Exact</code></td><td>yes</td><td>🟢 <code>Active</code></td></tr><tr><td><code>Exact</code></td><td>no (structure matched, content changed)</td><td>🟡 <code>Drifted</code></td></tr><tr><td><code>Relaxed</code></td><td>—</td><td>🟡 <code>Drifted</code></td></tr><tr><td><code>HashFallback</code></td><td>—</td><td>🟡 <code>Drifted</code></td></tr><tr><td><code>Failed</code></td><td>—</td><td>🔴 <code>Stale</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The query is never regenerated</p><p><code>heal_bookmark</code> re-resolves using the <em>original</em> stored query and records a new <code>Resolution</code> (new byte range, hash, location), but <code>Bookmark.query</code> is immutable after creation. The tiered fallback is the entire drift-recovery mechanism; the query is the durable anchor, resolutions are the moving history.</p></div><h2 id="where-health-physically-lives" tabindex="-1">Where health physically lives <a class="header-anchor" href="#where-health-physically-lives" aria-label="Permalink to &quot;Where health physically lives&quot;">​</a></h2><p>Health is <strong>not</strong> stored on the bookmarks table. The <code>resolutions</code> table holds <code>health</code> and <code>method</code>; <code>bookmarks</code> only keeps a <code>current_resolution_id</code> pointer. A bookmark&#39;s displayed health is its <em>current resolution&#39;s</em> health, fetched via a join.</p><h2 id="the-content-hash" tabindex="-1">The content hash <a class="header-anchor" href="#the-content-hash" aria-label="Permalink to &quot;The content hash&quot;">​</a></h2><p><code>content_hash</code> is <code>sha256:</code> + 16 hex chars, computed over whitespace-normalized text:</p><ol><li>Trim each line and collapse intra-line whitespace runs to a single space.</li><li>Collapse consecutive blank lines to one; drop leading/trailing blanks.</li><li>SHA-256 the result, take the first 8 bytes → 16 hex chars.</li></ol><p>This normalization is exactly what lets a bookmark survive reformatting (indentation changes, trailing whitespace, blank-line counts) while still distinguishing different identifiers.</p><p>The hash is used three ways: disambiguating among multiple structural matches, the Tier-4 fallback walk, and feeding the <code>hash_matches</code> flag into health transitions.</p><h2 id="heal-vs-validate" tabindex="-1">Heal vs. validate <a class="header-anchor" href="#heal-vs-validate" aria-label="Permalink to &quot;Heal vs. validate&quot;">​</a></h2><p><code>heal_bookmark</code> is the write path; <code>validate</code> runs the same resolution with no database writes.</p><ul><li><strong>Heal</strong> (1) checks a git-ancestry gate — it won&#39;t heal &quot;backward&quot; in history unless forced; (2) resolves; (3) computes health; (4) optionally auto-archives stale bookmarks; (5) inserts a deduplicated <code>Resolution</code> row and repoints the bookmark; (6) recomputes the health of every collection containing it.</li><li><strong>Validate</strong> (<code>--validate-only</code>) skips all writes but still reports the method, health, and location — a dry run.</li></ul><p>Resolution history is capped (default 20 entries per bookmark) and deduplicated: re-healing at the same location across unrelated commits updates the existing row rather than creating noise.</p><h2 id="collection-health" tabindex="-1">Collection health <a class="header-anchor" href="#collection-health" aria-label="Permalink to &quot;Collection health&quot;">​</a></h2><p>A collection&#39;s health is the worst of its bookmarks: <code>stale &gt; drifted &gt; active</code>, with <code>archived</code> bookmarks excluded. The TUI computes this live for previews; the database stores a cached value.</p>',22))])}const T=s(u,[["render",m]]);export{y as __pageData,T as default};
